class Node:
    def __init__(self, value, next=None):
        self.value = value
        self.next = next

def build(values):
    head = None
    for v in reversed(values):
        head = Node(v, head)
    return head

def values(head):
    result = []
    while head is not None:
        result.append(head.value)
        head = head.next
    return result

def solve(items):
    current = build(items)
    previous = None
    while current is not None:
        following = current.next
        current.next = following
        previous = current
        current = following
    return values(previous)

print(solve([3, 8, 2, 5]))

